from pathlib import Path
root=Path('/mnt/data/TradePulsePro')
nav='''<nav class="nav"><a href="dashboard.html">◈ Painel</a><a href="risco.html">🛡️ Gestão de risco</a><a href="alertas.html">🔔 Alertas</a><a href="simulador.html">🧪 Simulador</a><a href="backtest.html">📈 Backtesting</a><a href="desempenho.html">📊 Desempenho</a><a href="conexao.html">🔌 Conexão</a></nav>'''
def shell(title,desc,body,script=''):
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#070c16"><title>{title} · TradePulse Pro</title><link rel="stylesheet" href="common.css"></head><body><header><div class="brand">◈ TradePulse <em>PRO</em> <span class="live">LIVE MARKET</span></div><div class="market-mini" id="marketStatus">Dados de mercado públicos<br><span id="headerPrice">Carregando preço…</span></div></header>{nav}<main><h1 class="page-title">{title}</h1><p class="lead">{desc}</p>{body}</main><footer>TradePulse Pro · Ferramentas educativas. Não é recomendação financeira. Dados públicos sujeitos a atraso ou indisponibilidade.</footer><script src="common.js"></script><script>async function updateHeader(){{try{{const t=await TP.ticker();document.getElementById('headerPrice').textContent=TP.coin.replace('USDT','')+' '+TP.money(+t.lastPrice)+' · 24h '+(+t.priceChangePercent).toLocaleString('pt-BR',{{maximumFractionDigits:2}})+'%';}}catch(e){{document.getElementById('headerPrice').textContent='Mercado indisponível';}}}}updateHeader();document.addEventListener('tp-coin-change',updateHeader);setInterval(updateHeader,15000);</script><script>{script}</script></body></html>'''

risk_body='''<section class="grid"><article class="card"><h2>Calculadora de tamanho da posição</h2><p class="muted">Estima a quantidade com base no capital que você aceita arriscar. Não inclui taxas, slippage, funding ou gaps.</p><div class="form"><div class="field"><label>Ativo</label><select id="coin" data-coin-select></select></div><div class="field"><label>Direção</label><select id="side"><option value="long">Compra / Long</option><option value="short">Venda / Short</option></select></div><div class="field"><label>Capital (US$)</label><input id="capital" type="number" min="0" value="1000" step="any"></div><div class="field"><label>Risco por operação (%)</label><input id="riskPct" type="number" min="0.1" max="100" value="1" step="0.1"></div><div class="field"><label>Entrada (US$)</label><input id="entry" type="number" min="0" step="any" placeholder="Preço de entrada"></div><div class="field"><label>Stop-loss (US$)</label><input id="stop" type="number" min="0" step="any" placeholder="Preço de stop"></div><div class="field"><label>Take-profit (US$)</label><input id="target" type="number" min="0" step="any" placeholder="Preço-alvo"></div></div><div class="actions"><button class="btn primary" id="calc">Calcular</button><button class="btn" id="current">Usar preço atual</button></div><div class="stats"><div class="stat"><span>Risco máximo</span><b id="riskAmt">—</b></div><div class="stat"><span>Quantidade estimada</span><b id="qty">—</b></div><div class="stat"><span>Valor da posição</span><b id="notional">—</b></div><div class="stat"><span>Perda no stop</span><b id="loss">—</b></div><div class="stat"><span>Ganho no alvo</span><b id="profit">—</b></div><div class="stat"><span>Risco / retorno</span><b id="rr">—</b></div></div><p class="muted" id="msg">Preencha entrada, stop e alvo.</p></article><article class="card"><h2>Regras básicas de risco</h2><p class="muted">Sugestões de checklist — ajuste à sua estratégia e tolerância ao risco.</p><div class="list"><div class="item"><div><b>Defina o risco antes de entrar</b><div class="detail">Calcule o tamanho da posição antes de abrir a operação.</div></div></div><div class="item"><div><b>Evite mover o stop para aumentar a perda</b><div class="detail">Um stop não garante execução exata em mercado volátil.</div></div></div><div class="item"><div><b>Inclua custos e alavancagem</b><div class="detail">Taxas e slippage podem alterar o resultado real.</div></div></div></div><div class="warn">Este cálculo é apenas estimativo. Não garante limite de perda nem rentabilidade. Criptoativos podem causar perda substancial do capital.</div></article></section>'''
risk_js='''const $=id=>document.getElementById(id);let live=0;async function refresh(){try{live=await TP.price();}catch{}}function calc(){const c=+$('capital').value,p=+$('riskPct').value,e=+$('entry').value,s=+$('stop').value,t=+$('target').value,side=$('side').value;const ok=c>0&&p>0&&p<=100&&e>0&&s>0&&(side==='long'?s<e:s>e);if(!ok){['riskAmt','qty','notional','loss','profit','rr'].forEach(i=>$(i).textContent='—');$('msg').textContent='Confira os valores. Long: stop abaixo da entrada; Short: stop acima.';return}const r=c*p/100,q=r/Math.abs(e-s),gain=t>0&&(side==='long'?t>e:t<e)?Math.abs(t-e)*q:null;$('riskAmt').textContent=TP.money(r);$('qty').textContent=TP.num(q,8);$('notional').textContent=TP.money(q*e);$('loss').textContent=TP.money(q*Math.abs(e-s));$('profit').textContent=gain===null?'Alvo inválido':TP.money(gain);$('rr').textContent=gain===null?'—':TP.num(gain/r,2)+' : 1';$('msg').textContent='Estimativa antes de taxas, slippage, funding e gaps.'} $('calc').onclick=calc;['capital','riskPct','entry','stop','target','side'].forEach(i=>$(i).addEventListener('input',calc));$('current').onclick=async()=>{await refresh();if(live){$('entry').value=live;calc()}else alert('Não foi possível obter o preço atual. Tente novamente.')} ;refresh();'''
(root/'risco.html').write_text(shell('Gestão de risco','Dimensione operações antes de entrar no mercado e avalie o risco/retorno estimado.',risk_body,risk_js),encoding='utf-8')

alerts_body='''<section class="grid"><article class="card"><h2>Criar alerta de preço</h2><p class="muted">Alertas vinculados à moeda selecionada e compartilhados com as outras páginas deste navegador.</p><div class="form"><div class="field"><label>Ativo</label><select id="coin" data-coin-select></select></div><div class="field"><label>Condição</label><select id="condition"><option value="above">Preço acima de</option><option value="below">Preço abaixo de</option></select></div><div class="field"><label>Preço-alvo (US$)</label><input id="target" type="number" min="0" step="any" placeholder="Ex.: 70000"></div></div><div class="actions"><button class="btn primary" id="add">＋ Criar alerta</button><button class="btn" id="notify">Ativar notificações</button><button class="btn" id="refresh">Verificar agora</button></div><p class="muted" id="status">A página precisa permanecer aberta para monitorar os alertas.</p></article><article class="card"><h2>Como funcionam</h2><p class="muted">O navegador verifica o preço público periodicamente enquanto esta página está aberta. Alertas não são enviados pela corretora e podem não disparar se a conexão cair, a aba for suspensa ou o dispositivo dormir.</p><div class="warn">Notificações do sistema exigem permissão do navegador e podem depender de HTTPS. Não confie em alertas locais como único mecanismo de proteção de uma operação.</div></article></section><section class="card" style="margin-top:15px"><h2>Seus alertas</h2><div id="alerts" class="list"><div class="empty">Carregando…</div></div></section>'''
alerts_js='''const $=id=>document.getElementById(id),KEY='tp.alertas.v1';let rows=TP.read(KEY,[]),timer=null;function render(){if(!rows.length){$('alerts').innerHTML='<div class="empty">Nenhum alerta criado.</div>';return}$('alerts').innerHTML=rows.map(a=>`<div class="item"><div><b>${TP.escape(a.coin)} · ${a.tipo==='above'?'Acima de':'Abaixo de'} ${TP.money(a.preco)}</b><div class="detail">${a.disparado?'✓ Disparado':'Aguardando condição'} · Criado ${new Date(a.criado||Date.now()).toLocaleString('pt-BR')}</div></div><button class="btn danger" data-del="${a.id}">Remover</button></div>`).join('');document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{rows=rows.filter(a=>a.id!==b.dataset.del);TP.save(KEY,rows);render()})}async function check(){try{const symbols=[...new Set(rows.filter(a=>!a.disparado).map(a=>a.coin))];for(const sym of symbols){const price=await TP.price(sym);let changed=false;rows.forEach(a=>{if(a.coin===sym&&!a.disparado&&(a.tipo==='above'?price>=a.preco:price<=a.preco)){a.disparado=true;changed=true;const msg=`${sym} atingiu ${TP.money(price)} (alvo ${TP.money(a.preco)}).`;$('status').textContent=msg;if('Notification'in window&&Notification.permission==='granted')try{new Notification('TradePulse Pro · Alerta',{body:msg})}catch{}}});if(changed){TP.save(KEY,rows);render()}}if(!symbols.length)$('status').textContent='Nenhum alerta pendente para monitorar.'}catch(e){$('status').textContent='Não foi possível verificar agora; confira a conexão.'}}$('add').onclick=()=>{const p=+$('target').value;if(!(p>0)){alert('Informe um preço válido.');return}rows.unshift({id:String(Date.now())+Math.random().toString(16).slice(2,6),coin:$('coin').value,tipo:$('condition').value,preco:p,criado:Date.now(),disparado:false});TP.save(KEY,rows);$('target').value='';render();check()};$('notify').onclick=async()=>{if(!('Notification'in window)){alert('Este navegador não oferece notificações.');return}const p=await Notification.requestPermission();$('status').textContent=p==='granted'?'Notificações ativadas.':'Permissão não concedida.'};$('refresh').onclick=check;render();check();timer=setInterval(check,15000);'''
(root/'alertas.html').write_text(shell('Alertas de preço','Acompanhe níveis de preço definidos por você. Os alertas são locais e não enviam ordens.',alerts_body,alerts_js),encoding='utf-8')

sim_body='''<section class="grid"><article class="card"><h2>Registrar operação fictícia</h2><p class="muted">Paper trading: acompanhe uma estratégia sem enviar ordens para uma corretora.</p><div class="form"><div class="field"><label>Ativo</label><select id="coin" data-coin-select></select></div><div class="field"><label>Direção</label><select id="side"><option value="long">Compra / Long</option><option value="short">Venda / Short</option></select></div><div class="field"><label>Entrada (US$)</label><input id="entry" type="number" min="0" step="any" placeholder="Vazio = preço atual"></div><div class="field"><label>Quantidade</label><input id="qty" type="number" min="0" step="any" value="0.001"></div><div class="field"><label>Stop-loss (opcional)</label><input id="stop" type="number" min="0" step="any"></div><div class="field"><label>Take-profit (opcional)</label><input id="target" type="number" min="0" step="any"></div><div class="field" style="grid-column:1/-1"><label>Nota da estratégia</label><input id="note" maxlength="100" placeholder="Ex.: cruzamento EMA 9/21"></div></div><div class="actions"><button class="btn primary" id="open">＋ Abrir trade simulado</button><button class="btn" id="refresh">Atualizar preços</button><button class="btn danger" id="clear">Limpar fechados</button></div><p class="muted" id="status">P&L estimado sem taxas. Os registros ficam neste navegador.</p></article><article class="card"><h2>Resumo da carteira simulada</h2><div class="stats"><div class="stat"><span>Abertas</span><b id="openCount">0</b></div><div class="stat"><span>P&L em aberto</span><b id="floating">US$ 0,00</b></div><div class="stat"><span>P&L fechado</span><b id="closed">US$ 0,00</b></div></div><div class="warn">Simulação educativa. O preço de fechamento é o preço público consultado no momento do clique, não uma execução real. Funding, taxas e slippage não são incluídos.</div></article></section><section class="card" style="margin-top:15px"><h2>Histórico de operações</h2><div class="list" id="trades"><div class="empty">Nenhuma operação registrada.</div></div></section>'''
sim_js='''const $=id=>document.getElementById(id),KEY='tp.papertrades.v1';let trades=TP.read(KEY,[]),prices={};async function getPrice(sym){if(!prices[sym])prices[sym]=await TP.price(sym);return prices[sym]}function save(){TP.save(KEY,trades)}function render(){const open=trades.filter(t=>t.saida==null),closed=trades.filter(t=>t.saida!=null);let float=0;open.forEach(t=>{if(prices[t.coin])float+=(t.lado==='long'?prices[t.coin]-t.entrada:t.entrada-prices[t.coin])*t.qtd});const closedPnl=closed.reduce((s,t)=>s+(+t.pnl||0),0);$('openCount').textContent=open.length;$('floating').textContent=TP.money(float);$('floating').className=float>=0?'good':'bad';$('closed').textContent=TP.money(closedPnl);$('closed').className=closedPnl>=0?'good':'bad';if(!trades.length){$('trades').innerHTML='<div class="empty">Nenhuma operação registrada.</div>';return}$('trades').innerHTML=trades.slice(0,100).map(t=>{const isOpen=t.saida==null,px=prices[t.coin],pnl=isOpen?(px?(t.lado==='long'?px-t.entrada:t.entrada-px)*t.qtd:0):t.pnl;return `<div class="item"><div><b>${TP.escape(t.coin)} · ${t.lado==='long'?'LONG':'SHORT'} · ${isOpen?'ABERTO':'FECHADO'}</b><div class="detail">Entrada ${TP.money(t.entrada)} · Qtd. ${TP.num(t.qtd,8)}${t.stop?' · Stop '+TP.money(t.stop):''}${t.alvo?' · Alvo '+TP.money(t.alvo):''}<br>${isOpen?'Preço atual '+(px?TP.money(px):'carregando…'):'Saída '+TP.money(t.saida)}${t.nota?'<br>'+TP.escape(t.nota):''}</div></div><div style="text-align:right;flex-shrink:0"><b class="${pnl>=0?'good':'bad'}">${TP.money(pnl)}</b>${isOpen?`<div style="margin-top:6px"><button class="btn" data-close="${t.id}">Fechar agora</button></div>`:''}</div></div>`}).join('');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=async()=>{const t=trades.find(x=>x.id===b.dataset.close);try{t.saida=await getPrice(t.coin);t.pnl=(t.lado==='long'?t.saida-t.entrada:t.entrada-t.saida)*t.qtd;t.fechadoEm=Date.now();save();render()}catch(e){alert('Não foi possível obter o preço para fechar.')}})}async function updatePrices(){for(const t of trades.filter(t=>t.saida==null)){try{prices[t.coin]=await TP.price(t.coin)}catch{}}render()}$('open').onclick=async()=>{const coin=$('coin').value,side=$('side').value,qty=+$('qty').value;let entry=+$('entry').value;try{if(!(entry>0))entry=await getPrice(coin)}catch{alert('Não foi possível obter o preço atual. Informe uma entrada manual.');return}const stop=+$('stop').value,target=+$('target').value;if(!(qty>0)||!(entry>0)){alert('Informe entrada e quantidade válidas.');return}if(stop>0&&(side==='long'?stop>=entry:stop<=entry)){alert('Stop inválido para essa direção.');return}if(target>0&&(side==='long'?target<=entry:target>=entry)){alert('Alvo inválido para essa direção.');return}trades.unshift({id:String(Date.now())+Math.random().toString(16).slice(2,6),coin,lado:side,entrada:entry,qtd:qty,stop:stop||null,alvo:target||null,nota:$('note').value.trim(),abertoEm:Date.now(),saida:null,pnl:null});save();$('entry').value='';$('stop').value='';$('target').value='';$('note').value='';await updatePrices()};$('refresh').onclick=updatePrices;$('clear').onclick=()=>{if(confirm('Apagar todas as operações simuladas fechadas?')){trades=trades.filter(t=>t.saida==null);save();render()}};document.addEventListener('tp-coin-change',updatePrices);updatePrices();setInterval(updatePrices,15000);'''
(root/'simulador.html').write_text(shell('Simulador de trades','Treine entradas e saídas, acompanhe lucro/prejuízo estimado e mantenha o histórico conectado ao painel.',sim_body,sim_js),encoding='utf-8')

back_body='''<section class="grid"><article class="card"><h2>Configurar teste histórico</h2><p class="muted">Estratégia didática: cruzamento de médias exponenciais. Compra quando EMA curta cruza acima da longa e fecha quando cruza abaixo; posição Long ou Long/Short. O teste usa velas históricas públicas e não prevê o futuro.</p><div class="form"><div class="field"><label>Ativo</label><select id="coin" data-coin-select></select></div><div class="field"><label>Intervalo</label><select id="tf" data-tf-select><option value="5m">5 minutos</option><option value="15m">15 minutos</option><option value="1h">1 hora</option><option value="4h">4 horas</option><option value="1d">1 dia</option></select></div><div class="field"><label>Velas (máx. 1000)</label><input id="limit" type="number" min="100" max="1000" step="50" value="500"></div><div class="field"><label>EMA curta</label><input id="fast" type="number" min="2" max="100" value="9"></div><div class="field"><label>EMA longa</label><input id="slow" type="number" min="3" max="300" value="21"></div><div class="field"><label>Taxa estimada por lado (%)</label><input id="fee" type="number" min="0" max="2" step="0.01" value="0.1"></div><div class="field"><label>Modo</label><select id="mode"><option value="long">Somente Long</option><option value="both">Long e Short</option></select></div></div><div class="actions"><button class="btn primary" id="run">▶ Executar backtest</button></div><p class="muted" id="status">Carrega velas históricas da API pública da Binance.</p></article><article class="card"><h2>Resultados do backtest</h2><div class="stats"><div class="stat"><span>Retorno estratégia</span><b id="ret">—</b></div><div class="stat"><span>Retorno buy & hold</span><b id="hold">—</b></div><div class="stat"><span>Operações fechadas</span><b id="count">—</b></div><div class="stat"><span>Taxa de acerto</span><b id="win">—</b></div><div class="stat"><span>Drawdown máximo</span><b id="dd">—</b></div><div class="stat"><span>Patrimônio final</span><b id="equity">—</b></div></div><div class="warn">Backtest não garante resultados futuros. A simulação simplifica execução, spread, liquidez, slippage, impostos, funding e latência; os sinais usam fechamento das velas e podem ser sensíveis aos parâmetros.</div></article></section><section class="card" style="margin-top:15px"><h2>Últimas operações do teste</h2><div class="table-wrap"><table><thead><tr><th>Entrada</th><th>Saída</th><th>Direção</th><th>Preço entrada</th><th>Preço saída</th><th>Resultado %</th></tr></thead><tbody id="results"><tr><td colspan="6">Execute um teste para ver as operações.</td></tr></tbody></table></div></section>'''
back_js='''const $=id=>document.getElementById(id);function ema(vals,n){const out=Array(vals.length).fill(null),k=2/(n+1);let e;for(let i=0;i<vals.length;i++){e=e==null?vals[i]:vals[i]*k+e*(1-k);out[i]=e}return out}function pct(v){return (v*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'}$('run').onclick=async()=>{const btn=$('run');btn.disabled=true;btn.textContent='Carregando dados…';$('status').textContent='Consultando histórico público; aguarde.';try{const symbol=$('coin').value,tf=$('tf').value,limit=Math.max(100,Math.min(1000,+$('limit').value||500)),f=+$('fast').value,s=+$('slow').value,fee=Math.max(0,+$('fee').value||0)/100,mode=$('mode').value;if(f<2||s<=f)throw Error('A EMA longa precisa ser maior que a curta.');const candles=await TP.klines(symbol,tf,limit),cl=candles.map(c=>c.close),ef=ema(cl,f),es=ema(cl,s);let pos=0,entry=0,entryTime=0,equity=1,peak=1,maxDD=0,closed=[],curve=[];for(let i=1;i<cl.length;i++){let desired=pos;if(ef[i-1]<=es[i-1]&&ef[i]>es[i])desired=1;else if(ef[i-1]>=es[i-1]&&ef[i]<es[i])desired=mode==='both'?-1:0;if(mode==='long'&&desired<0)desired=0;if(desired!==pos){if(pos!==0){let gross=(cl[i]/entry-1)*pos;let net=(1+gross)*(1-fee)*(1-fee)-1;equity*=1+net;closed.push({entryTime,exitTime:candles[i].time,side:pos===1?'Long':'Short',entry,exit:cl[i],ret:net});peak=Math.max(peak,equity);maxDD=Math.max(maxDD,(peak-equity)/peak)}if(desired!==0){entry=cl[i];entryTime=candles[i].time}pos=desired;}curve.push(equity);peak=Math.max(peak,equity);maxDD=Math.max(maxDD,(peak-equity)/peak)}if(pos!==0){const i=cl.length-1;let gross=(cl[i]/entry-1)*pos,net=(1+gross)*(1-fee)*(1-fee)-1;equity*=1+net;closed.push({entryTime,exitTime:candles[i].time,side:pos===1?'Long':'Short',entry,exit:cl[i],ret:net});peak=Math.max(peak,equity);maxDD=Math.max(maxDD,(peak-equity)/peak)}const wins=closed.filter(t=>t.ret>0).length,hold=cl.at(-1)/cl[0]-1;$('ret').textContent=pct(equity-1);$('ret').className=equity>=1?'good':'bad';$('hold').textContent=pct(hold);$('count').textContent=closed.length;$('win').textContent=closed.length?pct(wins/closed.length):'—';$('dd').textContent=pct(maxDD);$('equity').textContent=TP.money(equity*1000);$('status').textContent=`${symbol} · ${tf} · ${candles.length} velas · ${new Date(candles[0].time).toLocaleString('pt-BR')} até ${new Date(candles.at(-1).time).toLocaleString('pt-BR')}. Capital-base de referência: US$ 1.000.`;$('results').innerHTML=closed.slice(-100).reverse().map(t=>`<tr><td>${new Date(t.entryTime).toLocaleString('pt-BR')}</td><td>${new Date(t.exitTime).toLocaleString('pt-BR')}</td><td>${t.side}</td><td>${TP.money(t.entry)}</td><td>${TP.money(t.exit)}</td><td class="${t.ret>=0?'good':'bad'}">${pct(t.ret)}</td></tr>`).join('')||'<tr><td colspan="6">Nenhuma operação gerada com esses parâmetros.</td></tr>';TP.save('tp.lastBacktest',{symbol,tf,fast:f,slow:s,fee:fee*100,mode,returnPct:equity-1,hold,maxDD,trades:closed.length,winRate:closed.length?wins/closed.length:0,at:Date.now()})}catch(e){$('status').textContent=e.message||'Falha ao executar backtest.';alert(e.message||'Falha ao executar backtest.')}finally{btn.disabled=false;btn.textContent='▶ Executar backtest'}};'''
(root/'backtest.html').write_text(shell('Backtesting de estratégias','Teste uma regra simples em candles históricos, compare com comprar e manter e veja drawdown e taxa de acerto.',back_body,back_js),encoding='utf-8')

perf_body='''<section class="grid"><article class="card"><h2>Desempenho do paper trading</h2><p class="muted">Métricas calculadas a partir das operações simuladas registradas neste navegador.</p><div class="stats"><div class="stat"><span>Total de operações</span><b id="total">0</b></div><div class="stat"><span>Fechadas</span><b id="closed">0</b></div><div class="stat"><span>Abertas</span><b id="open">0</b></div><div class="stat"><span>P&L realizado</span><b id="pnl">US$ 0,00</b></div><div class="stat"><span>Taxa de acerto</span><b id="win">—</b></div><div class="stat"><span>Fator de lucro</span><b id="pf">—</b></div></div><div class="actions"><button class="btn primary" id="refresh">Atualizar métricas</button><button class="btn" id="csv">Exportar CSV</button></div></article><article class="card"><h2>Último backtest</h2><div id="backtestSummary" class="empty">Ainda não há backtest salvo. Execute um teste na página Backtesting.</div><div class="actions"><a class="btn" href="backtest.html" style="text-decoration:none">Abrir backtesting →</a></div><div class="warn">O desempenho do simulador não é resultado de conta real. Métricas podem diferir da execução real devido a custos e condições de mercado.</div></article></section><section class="card" style="margin-top:15px"><h2>Operações fechadas</h2><div class="table-wrap"><table><thead><tr><th>Ativo</th><th>Direção</th><th>Entrada</th><th>Saída</th><th>Quantidade</th><th>P&L</th><th>Fechado em</th></tr></thead><tbody id="closedRows"><tr><td colspan="7">Sem operações fechadas.</td></tr></tbody></table></div></section>'''
perf_js='''const $=id=>document.getElementById(id);function refresh(){const ts=TP.read('tp.papertrades.v1',[]),closed=ts.filter(t=>t.saida!=null),open=ts.filter(t=>t.saida==null),pnls=closed.map(t=>+t.pnl||0),net=pnls.reduce((a,b)=>a+b,0),wins=pnls.filter(x=>x>0),losses=pnls.filter(x=>x<0),grossWin=wins.reduce((a,b)=>a+b,0),grossLoss=Math.abs(losses.reduce((a,b)=>a+b,0));$('total').textContent=ts.length;$('closed').textContent=closed.length;$('open').textContent=open.length;$('pnl').textContent=TP.money(net);$('pnl').className=net>=0?'good':'bad';$('win').textContent=closed.length?TP.num(wins.length/closed.length*100,1)+'%':'—';$('pf').textContent=grossLoss?TP.num(grossWin/grossLoss,2):(grossWin?'∞':'—');$('closedRows').innerHTML=closed.length?closed.slice().sort((a,b)=>(b.fechadoEm||0)-(a.fechadoEm||0)).map(t=>`<tr><td>${TP.escape(t.coin)}</td><td>${t.lado==='long'?'Long':'Short'}</td><td>${TP.money(t.entrada)}</td><td>${TP.money(t.saida)}</td><td>${TP.num(t.qtd,8)}</td><td class="${t.pnl>=0?'good':'bad'}">${TP.money(t.pnl)}</td><td>${t.fechadoEm?new Date(t.fechadoEm).toLocaleString('pt-BR'):'—'}</td></tr>`).join(''):'<tr><td colspan="7">Sem operações fechadas.</td></tr>';const b=TP.read('tp.lastBacktest',null);$('backtestSummary').innerHTML=b?`<b>${TP.escape(b.symbol)} · ${TP.escape(b.tf)}</b><p class="muted">EMA ${b.fast}/${b.slow} · retorno ${TP.num(b.returnPct*100,2)}% · buy & hold ${TP.num(b.hold*100,2)}% · ${b.trades} operações · drawdown ${TP.num(b.maxDD*100,2)}%</p><span class="muted">Executado em ${new Date(b.at).toLocaleString('pt-BR')}</span>`:'Ainda não há backtest salvo. Execute um teste na página Backtesting.'}function csv(){const ts=TP.read('tp.papertrades.v1',[]).filter(t=>t.saida!=null);const rows=[['ativo','direcao','entrada','saida','quantidade','pnl','aberto_em','fechado_em','nota'],...ts.map(t=>[t.coin,t.lado,t.entrada,t.saida,t.qtd,t.pnl,new Date(t.abertoEm).toISOString(),t.fechadoEm?new Date(t.fechadoEm).toISOString():'',t.nota||''])];const data='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8;'}));a.download='tradepulse-desempenho.csv';a.click();URL.revokeObjectURL(a.href)}$('refresh').onclick=refresh;$('csv').onclick=csv;refresh();'''
(root/'desempenho.html').write_text(shell('Desempenho e histórico','Acompanhe resultados realizados, taxa de acerto, fator de lucro e exporte o histórico simulado.',perf_body,perf_js),encoding='utf-8')

conn_body='''<section class="grid"><article class="card"><h2>Fonte de dados de mercado</h2><p class="muted">Selecione uma API pública para consultar preço e ticker. Não são solicitadas chaves privadas nem permissões de negociação.</p><div class="form"><div class="field"><label>Corretora / fonte</label><select id="source"><option value="binance">Binance · mercado público</option><option value="okx">OKX · mercado público</option></select></div><div class="field"><label>Ativo</label><select id="coin" data-coin-select></select></div></div><div class="actions"><button class="btn primary" id="test">Testar conexão</button></div><div class="stats"><div class="stat"><span>Status</span><b id="connStatus">Não testado</b></div><div class="stat"><span>Preço consultado</span><b id="connPrice">—</b></div><div class="stat"><span>Variação 24h</span><b id="connChange">—</b></div></div><p class="muted" id="connMsg">O painel principal usa a API pública da Binance para dados de mercado.</p></article><article class="card"><h2>Integração de conta em modo somente leitura</h2><p class="muted">Acesso a saldo, posições e histórico privado da sua conta exige uma chave de API com permissão estritamente de leitura. Em um site HTML estático, guardar a chave secreta no navegador não é seguro.</p><div class="list"><div class="item"><div><b>Permitido neste pacote</b><div class="detail">Preços, candles e estatísticas públicas, sem autenticação.</div></div></div><div class="item"><div><b>Não implementado sem backend seguro</b><div class="detail">Saldo privado, posições e ordens da conta, mesmo em modo leitura.</div></div></div><div class="item"><div><b>Arquitetura recomendada</b><div class="detail">Servidor próprio com variáveis de ambiente, criptografia, escopo somente leitura e logs sem segredos.</div></div></div></div></article></section><section class="card" style="margin-top:15px"><h2>Teste de API pública</h2><div id="tickerData" class="empty">Clique em “Testar conexão”.</div></section><div class="warn">Nunca cole uma API secret em uma página HTML, no chat ou em um arquivo distribuído. Desative saques e negociação nas permissões da chave. Para acesso privado real, esta aplicação precisa de um backend autenticado e seguro; esta versão não solicita nem armazena credenciais.</div>'''
conn_js='''const $=id=>document.getElementById(id);$('test').onclick=async()=>{const btn=$('test');btn.disabled=true;btn.textContent='Testando…';try{const symbol=$('coin').value,source=$('source').value;let t;if(source==='binance'){t=await TP.ticker(symbol);$('connPrice').textContent=TP.money(+t.lastPrice);$('connChange').textContent=TP.num(+t.priceChangePercent,2)+'%';$('connChange').className=+t.priceChangePercent>=0?'good':'bad';$('tickerData').innerHTML=`<b>Binance · ${TP.escape(symbol)}</b><p class="muted">Último preço: ${TP.money(+t.lastPrice)}<br>Máxima 24h: ${TP.money(+t.highPrice)}<br>Mínima 24h: ${TP.money(+t.lowPrice)}<br>Volume base 24h: ${TP.num(+t.volume,3)}<br>Volume cotado: ${TP.money(+t.quoteVolume)}</p>`}else{const pair=symbol.replace('USDT','-USDT');const r=await fetch('https://www.okx.com/api/v5/market/ticker?instId='+pair);if(!r.ok)throw Error('A API da OKX não respondeu');const j=await r.json();if(j.code!=='0'||!j.data?.[0])throw Error(j.msg||'Par indisponível na OKX');t=j.data[0];$('connPrice').textContent=TP.money(+t.last);$('connChange').textContent=t.open24h?TP.num((+t.last/+t.open24h-1)*100,2)+'%':'—';$('connChange').className=+t.last>=+t.open24h?'good':'bad';$('tickerData').innerHTML=`<b>OKX · ${TP.escape(pair)}</b><p class="muted">Último preço: ${TP.money(+t.last)}<br>Máxima 24h: ${TP.money(+t.high24h)}<br>Mínima 24h: ${TP.money(+t.low24h)}<br>Volume 24h: ${TP.num(+t.vol24h,3)}</p>`}$('connStatus').textContent='Conectado';$('connStatus').className='good';$('connMsg').textContent='Consulta concluída em '+new Date().toLocaleTimeString('pt-BR')+'. Dados públicos, sem acesso à conta.'}catch(e){$('connStatus').textContent='Falhou';$('connStatus').className='bad';$('connMsg').textContent=e.message||'Falha de conexão. Verifique a internet ou tente outra fonte.';$('tickerData').textContent=e.message||'Falha ao consultar a API.'}finally{btn.disabled=false;btn.textContent='Testar conexão'}};'''
(root/'conexao.html').write_text(shell('Conexões e fontes de dados','Teste fontes de mercado públicas e veja os requisitos para uma futura integração segura de conta somente leitura.',conn_body,conn_js),encoding='utf-8')

# landing index, so opening the folder entry is obvious
index_body='''<section class="grid"><article class="card"><h2>Terminal de mercado</h2><p class="muted">Acesse o painel com gráficos candlestick, indicadores técnicos e dados de mercado. Todas as páginas compartilham a seleção de ativo e os dados locais do simulador.</p><div class="actions"><a class="btn primary" href="dashboard.html" style="text-decoration:none">Abrir painel de mercado →</a></div></article><article class="card"><h2>Ferramentas de trading</h2><div class="list"><div class="item"><div><b>Gestão de risco</b><div class="detail">Tamanho da posição, stop e risco/retorno.</div></div><a class="btn" href="risco.html">Abrir</a></div><div class="item"><div><b>Alertas</b><div class="detail">Monitoramento local de preços.</div></div><a class="btn" href="alertas.html">Abrir</a></div><div class="item"><div><b>Simulador</b><div class="detail">Operações fictícias sem ordens reais.</div></div><a class="btn" href="simulador.html">Abrir</a></div><div class="item"><div><b>Backtesting</b><div class="detail">Teste cruzamento de EMAs em histórico público.</div></div><a class="btn" href="backtest.html">Abrir</a></div><div class="item"><div><b>Desempenho</b><div class="detail">Métricas e exportação CSV.</div></div><a class="btn" href="desempenho.html">Abrir</a></div><div class="item"><div><b>Conexão</b><div class="detail">Teste Binance/OKX público e requisitos de integração segura.</div></div><a class="btn" href="conexao.html">Abrir</a></div></div></article></section><div class="warn">Dica: mantenha todos os arquivos extraídos na mesma pasta e abra index.html. O navegador precisa de internet para carregar dados públicos e a biblioteca de gráficos. Os dados locais são armazenados no navegador usado.</div>'''
(root/'index.html').write_text(shell('Seu terminal de trading','TradePulse Pro foi organizado em páginas separadas, com navegação compartilhada e dados locais sincronizados entre ferramentas.',index_body),encoding='utf-8')

readme='''TRADEPULSE PRO — VERSÃO MULTIPÁGINA\n\nCOMO ABRIR\n1. Extraia o ZIP inteiro para uma pasta.\n2. Abra index.html no navegador.\n3. Para gráficos, preços e backtesting, mantenha conexão com a internet.\n4. Todos os arquivos HTML, common.css e common.js devem permanecer juntos na mesma pasta.\n\nPÁGINAS\n- index.html: início e atalhos\n- dashboard.html: painel de mercado original com gráficos/indicadores e módulos de risco/alertas/simulador\n- risco.html: calculadora de gestão de risco\n- alertas.html: alertas locais de preço\n- simulador.html: paper trading\n- backtest.html: backtesting de cruzamento EMA\n- desempenho.html: métricas, histórico e exportação CSV\n- conexao.html: teste de APIs públicas Binance e OKX\n\nSINCRONIZAÇÃO\nAs páginas usam localStorage do mesmo navegador/perfil para compartilhar seleção de ativo, alertas, trades simulados e último backtest. Isso não sincroniza automaticamente entre dispositivos ou navegadores.\n\nLIMITAÇÕES E SEGURANÇA\n- Os alertas locais só são verificados enquanto a página estiver aberta e o navegador estiver ativo.\n- Paper trading é simulação e não envia ordens reais.\n- Backtesting é uma simulação simplificada e não prevê resultados futuros.\n- A página Conexão consulta endpoints públicos de mercado. Ela NÃO lê saldos/posições privados de uma conta. Para uma integração privada realmente somente leitura, implemente backend próprio seguro; não guarde API secrets no HTML ou localStorage.\n- As APIs públicas e a biblioteca de gráficos dependem de conexão e podem ficar indisponíveis.\n- Não é recomendação financeira.\n'''
(root/'LEIA-ME.txt').write_text(readme,encoding='utf-8')
print('pages:', [p.name for p in root.iterdir()])
